package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes: the original implementation scanned the input one
// character at a time, threading a header level, a list depth, a
// "header seen" flag and a list-open flag through a single loop, and it
// balanced the open tags at the end of the string. The behavior it
// implements is line-oriented, so this rewrite works on whole lines
// instead:
//
//  1. emphasis markers are substituted up front (first __…__ pair and
//     first _…_ pair),
//  2. the input is split into lines,
//  3. each line is rendered as a header (<h1>..<h6>), a list item
//     (grouped in a <ul>), or a <p> paragraph.
//
// Lines with 7 or more leading '#' characters are not valid markdown
// headers and fall through to paragraph rendering, matching the
// original behavior.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var b strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			b.WriteString("</ul>")
			inList = false
		}
		switch {
		case isListItem(line):
			if !inList {
				b.WriteString("<ul>")
				inList = true
			}
			b.WriteString("<li>" + listItemText(line) + "</li>")
		case headerLevel(line) > 0:
			writeHeader(&b, line)
		default:
			b.WriteString("<p>" + line + "</p>")
		}
	}
	if inList {
		b.WriteString("</ul>")
	}
	return b.String()
}

// applyEmphasis rewrites the first __…__ pair as <strong>…</strong> and
// the first _…_ pair as <em>…</em>. This mirrors the four
// strings.Replace calls the original implementation made before scanning.
func applyEmphasis(s string) string {
	s = strings.Replace(s, "__", "<strong>", 1)
	s = strings.Replace(s, "__", "</strong>", 1)
	s = strings.Replace(s, "_", "<em>", 1)
	s = strings.Replace(s, "_", "</em>", 1)
	return s
}

// isListItem reports whether the line is an unordered list item, i.e. it
// starts with '*'.
func isListItem(line string) bool {
	return strings.HasPrefix(line, "*")
}

// listItemText returns the text of a list item, dropping the leading '*'
// and the single space that follows it.
func listItemText(line string) string {
	text := strings.TrimPrefix(line, "*")
	return strings.TrimPrefix(text, " ")
}

// headerLevel returns the level of the markdown header the line starts
// with, or 0 if the line is not a header. Lines with 7 or more leading
// '#' characters are not valid markdown headers.
func headerLevel(line string) int {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level > 6 {
		return 0
	}
	return level
}

// writeHeader renders a header line as an <hN> element, where N is the
// number of leading '#' characters. It must only be called for lines
// with headerLevel > 0.
func writeHeader(b *strings.Builder, line string) {
	level := headerLevel(line)
	text := strings.TrimPrefix(line, strings.Repeat("#", level))
	text = strings.TrimPrefix(text, " ")
	fmt.Fprintf(b, "<h%d>%s</h%d>", level, text, level)
}
